// PERF benchmark — 2026-11-11 性能定量实测 round (ROADMAP §4.1 "性能实测").
//
// Turns the three ☐ items into measured numbers, entirely headless (no GUI,
// no mpv core):
//
//   1. scan throughput: LibraryStore scans a 2000-file synthetic library
//      (fixture generated by tools/gen_perf_fixture.sh into /tmp) — once
//      through the production worker-isolate path (requestScan), once
//      through the direct walk with the real progress callback, so the
//      throttled-callback count is measured, not derived.
//   2. first-frame load path: the JSON stores load synchronously in their
//      constructors before runApp (MediaStores.init, lib/media/media_stores.dart:115;
//      LibraryStore._load reads + jsonDecodes library.json at
//      lib/media/library_store.dart:729-736) — the constructor on a
//      2000-entry library.json is timed here, plus a raw jsonDecode
//      median. The document is built from the real scan when the fixture
//      exists, synthesized otherwise (identical shape/size, so CI still
//      gets a representative number without the fixture).
//   3. thumbnail serial-chain throughput: N jobs through ThumbnailService
//      with a stub ffmpeg of known per-job cost (guard-test stub shape,
//      test/performance_guards_test.dart:161) — measured ms/job and jobs/s,
//      with the same flock(1) concurrent-invocation marker proving zero
//      overlap in the measured run.
//
// CALIBRATION CAVEAT (repeated in every report line): every number below is
// 容器 Isolate 计时 — wall clock inside this flutter_tester VM process on the
// container that ran the benchmark. It is NOT a host baseline: shared
// cores, container FS behavior and the tester harness all shift it. The
// numbers quantify the ALGORITHmic cost (per-file yield walk, throttled
// progress, sync JSON load) at 2000-entry scale; host hardware numbers
// stay with the manual acceptance round (SPEC §9).
//
// Fixture missing (CI, any machine without /tmp/emoplay-perf-lib): sections
// 1/3 print a skip line and return — the audio_probe_test.dart pattern;
// section 2's raw jsonDecode still runs on a synthesized document (pure
// compute, no fixture).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import 'package:emoplay/media/library_store.dart';
import 'package:emoplay/media/thumbnail_service.dart';

const fixtureRoot = '/tmp/emoplay-perf-lib';
const fixtureFiles = 2000;

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  late Directory tempDir;
  setUp(() async {
    tempDir = await Directory.systemTemp.createTemp('emoplay-perf-bench-');
  });
  tearDown(() async {
    try {
      await tempDir.delete(recursive: true);
    } catch (_) {}
  });

  Future<void> pumpUntil(
    bool Function() condition, {
    Duration timeout = const Duration(seconds: 60),
  }) async {
    final deadline = DateTime.now().add(timeout);
    while (!condition()) {
      if (DateTime.now().isAfter(deadline)) {
        fail('condition not met within $timeout');
      }
      await Future<void>.delayed(const Duration(milliseconds: 5));
    }
  }

  // Whole-process RSS hint from /proc/self/status (Linux; null elsewhere —
  // printed as 'n/a', it is a hint, never a leak verdict).
  int? readRssHintKb() {
    if (!Platform.isLinux) {
      return null;
    }
    try {
      for (final line in File('/proc/self/status').readAsLinesSync()) {
        if (line.startsWith('VmRSS:')) {
          return int.parse(line.split(RegExp(r'\s+'))[1]);
        }
      }
    } catch (_) {}
    return null;
  }

  // A 2000-entry library.json with the exact _save() shape
  // (lib/media/library_store.dart:777-783). Uses the real scan output when
  // the fixture exists; otherwise synthesized entries of comparable length.
  Future<File> writeLibraryJson(List<LibraryEntry> entries) async {
    final file = File('${tempDir.path}/library.json');
    await file.writeAsString(jsonEncode(<String, Object?>{
      'version': 1,
      'directories': [fixtureRoot],
      'entries': [for (final e in entries) e.toJson()],
    }));
    return file;
  }

  Future<List<LibraryEntry>> realEntriesOrSynthetic() async {
    if (Directory(fixtureRoot).existsSync()) {
      return LibraryStore.scanDirectories(
          [fixtureRoot], const ScanOptions());
    }
    // Synthetic stand-in: same field shapes, ~40-char paths, 1/4 stamped.
    return [
      for (var i = 0; i < fixtureFiles; i++)
        LibraryEntry(
          path:
              '/tmp/emoplay-perf-lib/group${(i % 16).toString().padLeft(2, '0')}/'
              'sub${(i % 10).toString().padLeft(2, '0')}/clip${i.toString().padLeft(5, '0')}.mkv',
          title: 'clip${i.toString().padLeft(5, '0')}',
          type: i % 2 == 0 ? 'video' : 'audio',
          size: 4096,
          lastPlayed:
              i % 4 == 0 ? '2026-11-01T12:00:00.000Z' : '',
        ),
    ];
  }

  test('PERF scan throughput — worker isolate end-to-end (production path)',
      () async {
    if (!Directory(fixtureRoot).existsSync()) {
      // ignore: avoid_print
      print('PERF scan fixture missing — skipped');
      return;
    }
    final store = LibraryStore('${tempDir.path}/library.json');
    addTearDown(store.dispose);

    final notifications = <String>[];
    var lastFileCount = -1;
    store.addListener(() {
      notifications.add('${store.isScanning}:${store.scanFileCount}');
      if (store.scanFileCount != lastFileCount) {
        lastFileCount = store.scanFileCount;
      }
    });

    final rssBefore = readRssHintKb();

    final t0 = DateTime.now();
    expect(store.addDirectory(fixtureRoot), isTrue);
    await pumpUntil(() =>
        !store.isScanning && store.entryList.length == fixtureFiles);
    final firstScan = DateTime.now().difference(t0);

    final t1 = DateTime.now();
    store.requestScan();
    await pumpUntil(() =>
        !store.isScanning && store.entryList.length == fixtureFiles);
    final warmScan = DateTime.now().difference(t1);

    final rssAfter = readRssHintKb();

    // ignore: avoid_print
    print('PERF[scan-worker] entries=${store.entryList.length} '
        'firstScan=${firstScan.inMilliseconds}ms '
        '(includes isolate spawn) warmScan=${warmScan.inMilliseconds}ms '
        '=> ${(fixtureFiles / warmScan.inMilliseconds * 1000).toStringAsFixed(0)} files/s warm');
    // ignore: avoid_print
    print('PERF[scan-worker] store notifications during both scans='
        '${notifications.length} lastProgressFileCount=$lastFileCount');
    // ignore: avoid_print
    print('PERF[scan-worker] rssBefore='
        '${rssBefore == null ? 'n/a' : '${(rssBefore / 1024).toStringAsFixed(1)}MB'} '
        'rssAfter='
        '${rssAfter == null ? 'n/a' : '${(rssAfter / 1024).toStringAsFixed(1)}MB'} (whole-tester VmRSS hint, 非精确泄漏计量)');
    // ignore: avoid_print
    print('PERF calibration: 容器 Isolate 计时, 非宿主基线');
  }, timeout: const Timeout(Duration(minutes: 3)));

  test('PERF scan throughput — direct walk + real progress callback count',
      () async {
    if (!Directory(fixtureRoot).existsSync()) {
      // ignore: avoid_print
      print('PERF scan fixture missing — skipped');
      return;
    }

    final calls = <int>[];
    final t0 = DateTime.now();
    final entries = await LibraryStore.scanDirectories(
        [fixtureRoot], const ScanOptions(),
        progress: calls.add);
    final cold = DateTime.now().difference(t0);
    final coldCallCount = calls.length;

    final t1 = DateTime.now();
    calls.clear();
    final entries2 = await LibraryStore.scanDirectories(
        [fixtureRoot], const ScanOptions(),
        progress: calls.add);
    final warm = DateTime.now().difference(t1);
    final warmCallCount = calls.length;

    // ignore: avoid_print
    print('PERF[scan-walk] entries=${entries.length}/${entries2.length} '
        'cold=${cold.inMilliseconds}ms warm=${warm.inMilliseconds}ms '
        '=> ${(fixtureFiles / warm.inMilliseconds * 1000).toStringAsFixed(0)} files/s warm, '
        '${(fixtureFiles / cold.inMilliseconds * 1000).toStringAsFixed(0)} files/s cold');
    // ignore: avoid_print
    print('PERF[scan-walk] progress callback count cold=$coldCallCount '
        'warm=$warmCallCount '
        '(throttle: every 32nd file + final; per-file flooding would be $fixtureFiles)');
    // ignore: avoid_print
    print('PERF calibration: 容器 Isolate 计时, 非宿主基线');

    expect(entries, hasLength(fixtureFiles));
    expect(entries2, hasLength(fixtureFiles));
    expect(calls.length, fixtureFiles ~/ 32 + 1,
        reason: 'throttle step 32 (lib/media/library_store.dart:437) + final');
  }, timeout: const Timeout(Duration(minutes: 3)));

  test('PERF first-frame load path — LibraryStore ctor on 2000-entry json',
      () async {
    final entries = await realEntriesOrSynthetic();
    final file = await writeLibraryJson(entries);
    final bytes = file.lengthSync();
    final text = file.readAsStringSync();

    // Raw jsonDecode median over 20 runs — the dominant _load() stage.
    final decodeTimings = <int>[];
    for (var i = 0; i < 20; i++) {
      final t = DateTime.now();
      final doc = jsonDecode(text);
      decodeTimings.add(DateTime.now().difference(t).inMicroseconds);
      expect(doc, isA<Map>());
    }
    decodeTimings.sort();
    final decodeMedianUs = decodeTimings[decodeTimings.length ~/ 2];

    // Full constructor (readAsStringSync + jsonDecode + per-entry fromJson),
    // measured the way MediaStores.init pays it before runApp: synchronously.
    final ctorTimings = <int>[];
    for (var i = 0; i < 5; i++) {
      final t = DateTime.now();
      final store = LibraryStore(file.path);
      ctorTimings.add(DateTime.now().difference(t).inMicroseconds);
      expect(store.entryList, hasLength(fixtureFiles));
      expect(store.directories, [fixtureRoot]);
      store.dispose();
    }
    ctorTimings.sort();
    final ctorMedianMs = ctorTimings[2] / 1000;

    // ignore: avoid_print
    print('PERF[first-frame-load] library.json=${(bytes / 1024).toStringAsFixed(0)}KiB '
        '($fixtureFiles entries${Directory(fixtureRoot).existsSync() ? ', real scan output' : ', synthesized (fixture missing)'})');
    // ignore: avoid_print
    print('PERF[first-frame-load] jsonDecode median='
        '${(decodeMedianUs / 1000).toStringAsFixed(2)}ms '
        'LibraryStore ctor (full sync _load) median=${ctorMedianMs.toStringAsFixed(2)}ms');
    // ignore: avoid_print
    print('PERF calibration: 容器 Isolate 计时, 非宿主基线; 阈值判定按 >100ms 同步阻塞标准');
  }, timeout: const Timeout(Duration(minutes: 3)));

  test(
      'PERF thumbnail serial chain — measured throughput with stub ffmpeg',
      () async {
    final fixtureReady = Directory(fixtureRoot).existsSync();
    final shellAvailable = Platform.isLinux || Platform.isMacOS;
    final flockAvailable =
        shellAvailable && Process.runSync('which', ['flock']).exitCode == 0;
    if (!fixtureReady || !shellAvailable || !flockAvailable) {
      // ignore: avoid_print
      print('PERF thumbnail section skipped '
          '(fixture=$fixtureReady shell=$shellAvailable flock=$flockAvailable)');
      return;
    }

    const queuedFiles = 24;
    const grabSleepMs = 30; // stub grab cost, stands in for a real -frames:v
    const probeSleepMs = 5; // stub duration-probe cost

    // First 24 non-hidden fixture files, as the model would queue them.
    final paths = Directory(fixtureRoot)
        .listSync()
        .whereType<File>()
        .where((f) =>
            !f.path.split('/').last.startsWith('.') &&
            LibraryStore.mediaTypeForSuffix(
                    f.path.split('.').last.toLowerCase())
                .isNotEmpty)
        .take(queuedFiles)
        .map((f) => f.path)
        .toList();
    expect(paths, hasLength(queuedFiles));

    final jpegPath = '${tempDir.path}/stub-image.bin';
    await File(jpegPath).writeAsString('stub-thumbnail-payload\n');
    final logPath = '${tempDir.path}/invocations.log';
    final lockPath = '${tempDir.path}/serial.lock';
    final script = File('${tempDir.path}/ffmpeg-stub.sh');
    await script.writeAsString('''
#!/bin/sh
# Same shape as the performance_guards_test.dart stub, with measured costs:
# duration probe sleeps ${probeSleepMs}ms, the -frames:v grab sleeps ${grabSleepMs}ms.
LOG='$logPath'
LOCK='$lockPath'
JPEG='$jpegPath'
PROBE='$probeSleepMs'
GRAB='$grabSleepMs'

printf '%s\\n' "\$*" >> "\$LOG"
exec 9>"\$LOCK"
if ! flock -n 9; then
  echo "CONCURRENT:\$*" >> "\$LOG"
fi
flock 9

case " \$* " in
  *" -version "*)
    echo "ffmpeg version 6.1.1-stub Copyright (c) stub"
    exit 0
    ;;
esac
case " \$* " in
  *" -frames:v "*)
    sleep \$(awk -v g="\$GRAB" 'BEGIN{print g/1000}')
    out=""
    for a in "\$@"; do out="\$a"; done
    cat "\$JPEG" > "\$out"
    exit 0
    ;;
esac

sleep \$(awk -v p="\$PROBE" 'BEGIN{print p/1000}')
echo "  Duration: 00:02:00.00, start: 0.000000" >&2
echo "At least one output file must be specified" >&2
exit 1
''');
    await Process.run('chmod', <String>['755', script.path]);

    final service =
        ThumbnailService('${tempDir.path}/thumbs', ffmpegBinary: script.path);
    addTearDown(service.dispose);
    await service.probe();
    expect(service.isAvailable, isTrue);

    final t0 = DateTime.now();
    for (final path in paths) {
      service.requestThumbnail(path);
    }
    await pumpUntil(
        () => paths.every(
            (path) => service.cachedThumbnailPath(path).isNotEmpty),
        timeout: const Duration(seconds: 60));
    final total = DateTime.now().difference(t0);

    final log = File(logPath).readAsStringSync();
    final invocations = log
        .split('\n')
        .where((line) => line.isNotEmpty && !line.startsWith('CONCURRENT:'))
        .length;
    final concurrent = log
        .split('\n')
        .where((line) => line.startsWith('CONCURRENT:'))
        .length;

    // ignore: avoid_print
    print('PERF[thumbnail-serial] jobs=$queuedFiles '
        'total=${total.inMilliseconds}ms '
        '=> ${(total.inMilliseconds / queuedFiles).toStringAsFixed(1)}ms/job '
        '(${(queuedFiles / (total.inMilliseconds / 1000)).toStringAsFixed(1)} jobs/s)');
    // ignore: avoid_print
    print('PERF[thumbnail-serial] ffmpeg invocations=$invocations '
        '(expected 1 probe + ${queuedFiles * 2}) concurrentOverlap=$concurrent '
        '(must stay 0 — serial contract)');
    // ignore: avoid_print
    print('PERF calibration: 容器 Isolate 计时, stub 成本为模拟值, 非宿主基线');

    expect(concurrent, 0, reason: 'two stub children overlapped');
    expect(invocations, 1 + queuedFiles * 2);
  }, timeout: const Timeout(Duration(minutes: 3)));
}
